export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin HOME=/root LANG=C.UTF-8
set -o pipefail
set -eu
cd /workspace/fx06
echo <base64 of test/sandbox/fixtures file> | base64 -d > docker06.sh; echo  | base64 -d > https-server.mjs; echo  | base64 -d > git06.sh
chmod +x docker06.sh git06.sh; sha256sum docker06.sh https-server.mjs git06.sh
mkdir -p tls && cd tls
openssl req -x509 -newkey rsa:2048 -nodes -days 2 -subj /CN=factory06-synthetic-ca -keyout ca-key.pem -out ca.pem 2>/dev/null
printf 'subjectAltName=DNS:localhost,DNS:fixture-service\nbasicConstraints=CA:FALSE\n' > ext.cnf
openssl req -newkey rsa:2048 -nodes -subj /CN=fixture-service -keyout server-key.pem -out server.csr 2>/dev/null
openssl x509 -req -in server.csr -CA ca.pem -CAkey ca-key.pem -CAcreateserial -days 2 -extfile ext.cnf -out server.pem 2>/dev/null
chmod 644 server-key.pem; openssl verify -CAfile ca.pem server.pem
